                  const delSummary = todayDels.map((d,i)=>({
                    id:d.id, stop:i+1, customer:d.customer, address:d.address,
                    window:d.delivery_window||"", notes:d.notes||"", items:(d.items||[]).map(x=>x.name).join(", ")
